import {createAncientTree} from '../src/trees.js';
function start(){const api=window.__plantStudy;if(!api?.study)return;const dead=new URLSearchParams(location.search).get('case')==='05',id=dead?'05':'03',tree=createAncientTree({dead,bark:false,volume:true,coreResolution:dead?96:112,coreBlend:.22,coreHollow:.50});api.mount(tree,{id,view:{target:[0,dead?3:9,0],yaw:.28,pitch:1.46,distance:dead?15:45,nearTarget:dead?[0,2,.2]:[-.1,12,.2],nearDistance:dead?3.7:8},ground:true,background:0x353c36,environmentIntensity:0,neutralStudio:true,ambient:.75,rim:.7,fog:dead?[25,85]:[60,150],shadowRadius:dead?6:13,time:0,dof:0});api.params.light=315;document.querySelector('#light').value=315;document.querySelector('#light').dispatchEvent(new Event('input'));api.setTime(0);document.querySelector('#reset').click();document.title=`植被自习${id} · 骨架与生长坐标检查`;document.querySelector('.edition').textContent=`STUDY ${id} · VOLUME R01`;document.querySelector('.brand small').textContent=`VEGETATION · FIELD NOTES ${id}`;document.querySelector('#cases').innerHTML=`<button class="active">${id} ${dead?'枯枝骨架':'古松骨架'}</button>`;document.querySelector('#title').textContent=dead?'枝干的转折':'先看树的骨架';document.querySelector('#subtitle').textContent=dead?'中空劈裂 · 父子附着 · 末梢渐细':'扭干 · 分层侧枝 · 1.7米人物尺度';document.querySelector('.scene-caption').classList.add('dark');document.querySelector('aside h2').textContent='融合核心，再看空洞';document.querySelector('aside > .muted').textContent='主干与主叉由保留身份的生长轴生成SDF，融合后挖出内腔与窗口。中性材质用于检查连续曲面；仍未应用04树皮或通过参考验形。';document.querySelector('.segmented').hidden=true;document.querySelector('#leaf-parameters').hidden=true;document.querySelector('#reference-macro').hidden=true;document.querySelector('.timeline').hidden=true;const e=tree.evidence();document.querySelector('#evidence-summary').textContent=`${e.axes} 条轴的父子连接与累计弧长坐标已检查。原作者工程未取得；04树皮材质未应用。`;document.querySelector('.evidence b').textContent='体积实验 · 未验形';const controls=document.createElement('section');controls.className='parameters';controls.innerHTML='<label>核心融合半径<output id="blend-out">0.22</output><input id="core-blend" type="range" min=".04" max=".5" step=".02" value=".22"></label><label>内腔半径比<output id="hollow-out">0.50</output><input id="core-hollow" type="range" min=".25" max=".70" step=".025" value=".50"></label><button id="rebuild-core">更新核心体积</button><label class="check"><input type="checkbox" id="core-axis-map">显示原生长轴归属</label><p class="muted" id="volume-stats"></p>';document.querySelector('.evidence').before(controls);const volumeStats=()=>{const s=tree.core.stats;document.querySelector('#volume-stats').textContent=`保留${tree.axes.length}条轴，核心融合${s.selectedAxes.length}条，${s.triangles.toLocaleString()}面。`;};document.querySelector('#rebuild-core').onclick=()=>{const blend=+document.querySelector('#core-blend').value,hollowRatio=+document.querySelector('#core-hollow').value;tree.rebuildCore({blend,hollowRatio});document.querySelector('#blend-out').textContent=blend.toFixed(2);document.querySelector('#hollow-out').textContent=hollowRatio.toFixed(2);volumeStats();api.invalidate();};document.querySelector('#core-axis-map').onchange=ev=>{tree.setCoreDebug(ev.target.checked);api.invalidate();};volumeStats();if(!dead){const label=document.createElement('label');label.className='check';label.innerHTML='<input type="checkbox" id="needles" checked>显示独立针叶';document.querySelector('.evidence').before(label);document.querySelector('#needles').onchange=ev=>{tree.setNeedles(ev.target.checked);api.invalidate();};}document.querySelector('#source-dialog').innerHTML='<button class="close" id="tree-source-close">关闭</button><h2>骨架老师与自习边界</h2><p>历史母体1.14的原 TreeDevelopmentGenerator 与原随机数函数已运行，固定样例138条轴、137条父子连接逐一核对，只有末级轴允许挂叶。完整原文件未修改。</p><p>此页借用父切线引导、逐级分枝、弧长坐标原则；古松/枯树的姿态和空洞是自习结构约束，不是 FYZ 或 strggle李青的原工程复刻。灰模尚未通过形态验收。官方Three.js r170 MarchingCubes原内核已用解析球核对体积与法线；SDF胶囊融合、内腔挖空和轴属性回传为独立扩展，不等同原Houdini工程。</p><p>04树皮保持冻结。这里仅留 u周向/v局部弧长/growthV累计弧长/junction衔接接口，没有加载失败树皮为成品。</p>';document.querySelector('#tree-source-close').onclick=()=>document.querySelector('#source-dialog').close();api.treeReady=true;}
window.addEventListener('vegetation-study-ready',start,{once:true});if(window.__plantStudy?.study)start();
